class Solution:
    def shortener(self, requests: list[list[str]]) -> list:
        alphabet="0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
        by_url={}
        by_code={}
        responses=[]
        def encode(n):
            out=""
            while n:
                out=alphabet[n%62]+out
                n//=62
            return out or "0"
        for method,value in requests:
            if method=="POST":
                if value not in by_url:
                    code=encode(len(by_url)+1)
                    by_url[value]=code
                    by_code[code]=value
                responses.append(by_url[value])
            else:responses.append(by_code.get(value))
        return responses

